// A adapter une seule fois : ID du document Grist.
const body = $input.first().json.body || {};
return [{
  json: {
    docId: 'cRP1WgZQv7KmwmVrUbuEF8',
    userId: Number(body.userId),
    boosterSize: 5
  }
}];

// Plus d'accroissement horaire : BoosterCount n'est modifie que par les
// codes d'evenement (redeem-code.json) et par l'ouverture d'un booster ici.
const config = $('Set Config').first().json;
const userRows = $('Get Users').all().map((i) => i.json);
const user = userRows.find((u) => u.id === config.userId);
if (!user) {
  throw new Error('Utilisateur introuvable (userId=' + config.userId + ')');
}

const boosterCount = user.BoosterCount || 0;

return [{
  json: {
    userId: config.userId,
    boosterCount,
    hasStock: boosterCount >= 1,
    pullsSinceTop: user.PullsSinceTopRarity || 0,
    totalPulls: user.TotalPulls || 0
  }
}];

// Grist encode les colonnes de type liste (Attachments, RefList) sous la
// forme ["L", id1, id2, ...] : "L" est un marqueur, pas une valeur.
function refId(v) { return Array.isArray(v) ? v[1] : v; }
function firstAttachment(v) {
  if (!Array.isArray(v) || !v.length) return null;
  const ids = v[0] === 'L' ? v.slice(1) : v;
  return ids.length ? ids[0] : null;
}

const config = $('Set Config').first().json;
const status = $('Compute Booster Status').first().json;
let pullsSinceTop = status.pullsSinceTop;
let totalPulls = status.totalPulls;

const raritiesRows = $('Get Rarities').all().map((i) => i.json);
const cardsRows = $('Get Cards').all().map((i) => i.json).filter((c) => c.Active);
const configRows = $('Get Config Table').all().map((i) => i.json);

const cardsByRarity = {};
for (const c of cardsRows) {
  const rId = refId(c.Rarity);
  if (!cardsByRarity[rId]) cardsByRarity[rId] = [];
  cardsByRarity[rId].push(c);
}

let pityThreshold = Infinity;
let topRarityId = null;
if (configRows.length) {
  pityThreshold = configRows[0].PityThreshold || Infinity;
  topRarityId = refId(configRows[0].TopRarity);
}

function weightedPick() {
  const total = raritiesRows.reduce((s, r) => s + (r.Weight || 0), 0);
  let roll = Math.random() * total;
  for (const r of raritiesRows) {
    roll -= (r.Weight || 0);
    if (roll <= 0) return r;
  }
  return raritiesRows[raritiesRows.length - 1];
}

const batchId = `${config.userId}-${Date.now()}`;
const nowEpoch = Math.floor(Date.now() / 1000);
const drawn = [];

for (let i = 0; i < config.boosterSize; i++) {
  pullsSinceTop++;
  let rarity;
  if (pullsSinceTop >= pityThreshold && topRarityId) {
    rarity = raritiesRows.find((r) => r.id === topRarityId) || weightedPick();
  } else {
    rarity = weightedPick();
  }
  if (rarity.id === topRarityId) pullsSinceTop = 0;

  const pool = (cardsByRarity[rarity.id] && cardsByRarity[rarity.id].length) ? cardsByRarity[rarity.id] : cardsRows;
  const card = pool[Math.floor(Math.random() * pool.length)];

  drawn.push({
    userId: config.userId,
    cardId: card.id,
    obtainedAt: nowEpoch,
    batchId,
    name: card.Name,
    artist: card.Artist,
    description: card.Description,
    imageId: firstAttachment(card.Image),
    rarity: { id: rarity.id, name: rarity.Name, key: rarity.Key, colorHex: rarity.ColorHex }
  });
}

totalPulls += config.boosterSize;
const newBoosterCount = status.boosterCount - 1;

return drawn.map((d) => ({ json: { ...d, pullsSinceTop, totalPulls, newBoosterCount } }));

const cards = $('Draw Cards').all().map((i) => ({
  cardId: i.json.cardId,
  name: i.json.name,
  artist: i.json.artist,
  description: i.json.description,
  imageId: i.json.imageId,
  rarity: i.json.rarity
}));
const last = $('Draw Cards').last().json;
return [{
  json: {
    cards,
    pity: { pullsSinceTop: last.pullsSinceTop },
    booster: { count: last.newBoosterCount }
  }
}];
